create or replace function public.nail_2nya_subscribe_customer_push(p_appointment_id uuid,p_token text,p_endpoint text,p_p256dh text,p_auth text) returns boolean language plpgsql security definer set search_path=public,extensions as $$ declare v_valid boolean; begin select exists(select 1 from public.nail_2nya_booking_tokens t where t.appointment_id=p_appointment_id and t.token_hash=extensions.digest(coalesce(p_token,'')::bytea,'sha256')) into v_valid; if not v_valid then return false; end if; if nullif(trim(p_endpoint),'') is null or nullif(trim(p_p256dh),'') is null or nullif(trim(p_auth),'') is null then return false; end if; insert into public.nail_2nya_customer_push_subscriptions(appointment_id,endpoint,p256dh,auth,active,updated_at) values(p_appointment_id,trim(p_endpoint),trim(p_p256dh),trim(p_auth),true,now()) on conflict(endpoint) do update set appointment_id=excluded.appointment_id,p256dh=excluded.p256dh,auth=excluded.auth,active=true,updated_at=now(); return true; end; $$; revoke all on function public.nail_2nya_subscribe_customer_push(uuid,text,text,text,text) from public; grant execute on function public.nail_2nya_subscribe_customer_push(uuid,text,text,text,text) to anon,authenticated;